import { lazy } from 'react';
import { ClipboardCheck as IcClipboardCheck, Forklift as IcForklift, IndianRupee as IcIndianRupee, Store as IcStore, Warehouse as IcWarehouse } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Warehouse & Stores — hub page for the Inventory menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 5 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'WarehouseCenter'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const WarehouseManagement = lazy(() => import('./WarehouseManagement'));
const WarehouseOperations = lazy(() => import('./WarehouseOperations'));
const StoresDashboard = lazy(() => import('./StoresDashboard'));
const StoresCostAnalysis = lazy(() => import('./StoresCostAnalysis'));
const QualityManagement = lazy(() => import('./QualityManagement'));

export const TABS = [
  { id: 'warehouse', label: 'Warehouse', icon: IcWarehouse, page: 'WarehouseManagement', Component: WarehouseManagement },
  { id: 'operations', label: 'Warehouse Operations', icon: IcForklift, page: 'WarehouseOperations', Component: WarehouseOperations },
  { id: 'stores', label: 'Stores Dashboard', icon: IcStore, page: 'StoresDashboard', Component: StoresDashboard },
  { id: 'cost', label: 'Stores Cost Analysis', icon: IcIndianRupee, page: 'StoresCostAnalysis', Component: StoresCostAnalysis },
  { id: 'inbound', label: 'Inbound Quality', icon: IcClipboardCheck, page: 'QualityManagement', Component: QualityManagement },
];

export default function WarehouseCenter({ setPage }) {
  return (
    <TabHub
      icon={IcWarehouse}
      eyebrow="Inventory"
      title="Warehouse & Stores"
      subtitle="Warehouse master, put-away and unit loads, department stores and inbound checks"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
